
export function policyInputHTML(state,{field,select,years}){
 const p=state.opi2Policy;
 return '<section class="policy-inputs"><div class="panel-head"><div><h3>특별경영성과급</h3><p class="subtitle">고과 등을 반영한 최종 세전 총액만 입력하세요. 빈칸은 영업이익 전망으로 자동 추정합니다.</p></div></div><div class="grid three">'+select('기부율','opi2Policy.donationRate',p.donationRate,[.002,.004,.006,.008,.01].map(v=>[v,(v*100).toFixed(1)+'%']))+'</div><div class="special-rows">'+years(state).map(y=>'<div class="special-row"><strong>'+y+'</strong>'+field(y+' 특별성과급 최종 세전 총액','opi2Policy.manualGrossByYear.'+y,p.manualGrossByYear[y],{unit:'원',step:1,max:100000000000,placeholder:'빈칸 = 전망 자동 추정'})+'<div class="special-method" id="special-method-'+y+'"></div></div>').join('')+'</div><p class="disclosure">직접 입력한 금액은 소속·고과·학술연수·전망 배수를 다시 적용하지 않습니다. 0원을 입력하면 미지급, 빈칸은 자동 추정입니다. 자동 추정에만 소속과 학술연수 조건을 반영합니다.</p><details><summary>간단한 계산 가정 보기</summary><p class="disclosure">세전 총액 기준으로 세금 49.5%, 보험 4.967%, 선택한 기부율을 먼저 공제한 나머지를 자사주로 가정합니다. 업무성과급은 별도 추가하지 않습니다. 성과 다음 해 4월 1일을 계산용 예정일로 두고 지급해·1년 뒤·2년 뒤 각 1/3씩 매각합니다.</p><p class="disclosure">주식에는 PSU와 동일한 하나의 예시 평가가격을 적용하며 매각까지 유지합니다. 연간 총소득으로 최종 세금·보험료를 다시 추정하고 선징수 차이는 과세 다음 해 현금 정산합니다. 실제 회사 지급·세무 처리와 다를 수 있습니다.</p></details></section>';
}
export function policyReviewHTML(){return '';}
